const clean = (s) => (s || '').replace(/\*\*/g, '').replace(/\*/g, '').replace(/\[\d+\]/g, '').replace(/\[|\]/g, '').replace(/^#+\s*/g, '').trim();

function getContent(nodeName) {
  try {
    const raw = $(nodeName).first().json;
    return raw.choices?.[0]?.message?.content || raw.content?.[0]?.text || '';
  } catch (e) { return ''; }
}

function getXBuilderRaw(nodeName) {
  try {
    const raw = $(nodeName).first().json;
    if (raw.choices?.[0]?.message?.content) return String(raw.choices[0].message.content);
    if (raw.output && Array.isArray(raw.output)) {
      const parts = [];
      for (const item of raw.output) {
        if (item.content) {
          if (typeof item.content === 'string') parts.push(item.content);
          else if (Array.isArray(item.content)) {
            for (const c of item.content) {
              if (c && c.text) parts.push(c.text);
              else if (typeof c === 'string') parts.push(c);
            }
          }
        }
        if (item.text) parts.push(item.text);
        if (item.message && item.message.content) {
          const mc = item.message.content;
          if (typeof mc === 'string') parts.push(mc);
        }
      }
      if (parts.length) return parts.join('\n');
    }
    if (raw.text) return String(raw.text);
    return JSON.stringify(raw).slice(0, 15000);
  } catch (e) { return ''; }
}

const startupsContent = getContent('Search Startup Funding');
const xBuilderContent = getContent('Search X Builder Insights');
const trendingContent = getContent('Search Trending Content');

function parsePipeLines(text, minPipes) {
  const results = [];
  for (const line of text.split('\n')) {
    const t = line.trim();
    if (t.includes('|') && (t.match(/\|/g) || []).length >= minPipes) {
      const parts = t.replace(/^[\d\-\*\.\)\]]+\s*/, '').split('|').map(p => clean(p));
      if (parts[0] && parts[0].length > 1) results.push(parts);
    }
  }
  return results;
}

function extractNumberedItems(text) {
  const results = [];
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i].trim();
    const m = t.match(/^\d+[\.\)\:]\s*(.+)/);
    if (m) {
      let item = clean(m[1]);
      if (item.length > 3 && item.length < 200) results.push(item);
    }
  }
  return results;
}

function extractBoldItems(text) {
  const results = [];
  const matches = text.match(/\*\*([^*]+)\*\*/g) || [];
  for (const m of matches) {
    const item = m.replace(/\*\*/g, '').trim();
    if (item.length > 2 && item.length < 100) results.push(item);
  }
  return results;
}

const skipWords = ['NAME', 'FUNDING', 'ROUND', 'DESCRIPTION', 'HEADLINE', 'COMPANY', 'CATEGORY', 'TOPIC', 'BIG', 'SMALL', 'EXAMPLE', 'AUTHOR', 'POST_SUMMARY'];

const startups = [];
const pipeStartups = parsePipeLines(startupsContent, 2);
for (const parts of pipeStartups) {
  if (skipWords.some(w => parts[0].toUpperCase().includes(w))) continue;
  const builderVal = (parts[6] || '').toLowerCase();
  if (builderVal && builderVal.includes('low') && !builderVal.includes('flow')) continue;
  startups.push({
    name: parts[0],
    funding: parts[1] || 'Unknown',
    round: parts[2] || 'Unknown',
    description: parts[3] || 'AI startup',
    investor: parts[4] || 'Unknown',
    tech: parts[5] || 'Unknown',
    builder_value: parts[6] || ''
  });
}
if (startups.length === 0) {
  const dollarPattern = /\$(\d+[\d\.]*\s*[MBK](?:illion)?)/gi;
  const lines = startupsContent.split('\n');
  for (const line of lines) {
    const t = clean(line);
    const dollarMatch = t.match(dollarPattern);
    if (dollarMatch && t.length > 10) {
      const name = t.replace(/^\d+[\.\)\:]\s*/, '').split(/[:\-\(\|]/)[0].trim();
      if (name.length > 1 && name.length < 80) {
        const funding = dollarMatch[0];
        const roundMatch = t.match(/\b(Seed|Pre-seed|Series [A-Z]|Series A|Series B|Series C)\b/i);
        startups.push({ name: clean(name), funding, round: roundMatch ? roundMatch[0] : 'Unknown', description: t.substring(0, 120), investor: 'Unknown', tech: 'Unknown', builder_value: '' });
      }
    }
  }
}
if (startups.length === 0) {
  const boldItems = extractBoldItems(startupsContent);
  const numbered = extractNumberedItems(startupsContent);
  const items = boldItems.length > 0 ? boldItems : numbered;
  for (const item of items.slice(0, 6)) {
    startups.push({ name: item.split(/[:\-\(\|]/)[0].trim().substring(0, 60), funding: 'See details', round: 'Recent', description: item.substring(0, 120), investor: 'Unknown', tech: 'Unknown', builder_value: '' });
  }
}

const xTips = [];
const pipeTips = parsePipeLines(xBuilderContent, 3);
for (const parts of pipeTips) {
  if (skipWords.some(w => parts[0].toUpperCase().includes(w))) continue;
  const rp = (parts[3] || '').toLowerCase();
  if (rp.includes('low') && !rp.includes('flow') && !rp.includes('below')) continue;
  if (!rp.includes('high') && !rp.includes('medium') && !rp.includes('med')) continue;
  const maybeUrl = (parts[4] || '').trim();
  const postUrl = maybeUrl.startsWith('http') ? maybeUrl : '';
  xTips.push({
    author: parts[0],
    post_summary: parts[1] || '',
    practical_takeaway: parts[2] || '',
    reel_potential: parts[3] || 'medium',
    post_snippet: '',
    post_url: postUrl
  });
}
if (xTips.length === 0) {
  const lines = xBuilderContent.split('\n');
  for (const line of lines) {
    const t = line.trim();
    if (t.length < 20) continue;
    if (t.includes('|') && (t.match(/\|/g) || []).length >= 2) {
      const p = t.replace(/^[\d\-\*\.\)\]]+\s*/, '').split('|').map(x => clean(x));
      if (p[0] && p[0].length > 1 && !skipWords.some(w => p[0].toUpperCase().includes(w))) {
        const mu = (p[4] || '').trim();
        xTips.push({ author: p[0], post_summary: p[1] || t.substring(0, 200), practical_takeaway: p[2] || '', reel_potential: 'medium', post_snippet: '', post_url: mu.startsWith('http') ? mu : '' });
      }
    }
    if (xTips.length >= 8) break;
  }
}

const trending = [];
const pipeTrending = parsePipeLines(trendingContent, 1);
for (const parts of pipeTrending) {
  if (skipWords.some(w => parts[0].toUpperCase().includes(w))) continue;
  trending.push({ topic: parts[0], platform: parts[1] || 'Instagram', angle: parts[2] || '' });
}
if (trending.length === 0) {
  const numbered = extractNumberedItems(trendingContent);
  const boldItems = extractBoldItems(trendingContent);
  const items = numbered.length >= 3 ? numbered : (boldItems.length >= 3 ? boldItems : numbered);
  for (const item of items.slice(0, 5)) {
    const topic = item.split(/[:\|]/)[0].trim().substring(0, 80);
    if (topic.length > 3) trending.push({ topic, platform: 'Instagram', angle: item.substring(0, 150) });
  }
}

return [{ json: {
  startups: startups.slice(0, 6),
  x_tips: xTips.slice(0, 8),
  trending: trending.slice(0, 5),
  raw_startups: startupsContent.substring(0, 500),
  raw_x_builders: xBuilderContent.substring(0, 800),
  raw_trending: trendingContent.substring(0, 500)
} }];

const enc = (s) => encodeURIComponent(s || '');
const buildUrl = (base, params) => base + '?' + Object.entries(params).map(([k, v]) => enc(k) + '=' + enc(v)).join('&');

const input = items[0].json;
const startups = input.startups || [];
const xTips = input.x_tips || [];
const trending = input.trending || [];
const webhookBase = 'https://modudhanu.app.n8n.cloud/webhook/instagram-content';

let emailBody = 'YOUR DAILY CONTENT PICKS\n';
emailBody += 'Startup links: full package (reel + carousel + caption). X Builder links: tip reel package. Trending: inspiration only.\n\n';

emailBody += '=============================================\n';
emailBody += 'STARTUP BREAKDOWNS\n';
emailBody += '=============================================\n\n';

for (let i = 0; i < startups.length; i++) {
  const s = startups[i];
  const url = buildUrl(webhookBase, { type: 'startup', name: s.name, funding: s.funding, round: s.round, desc: s.description });
  emailBody += (i + 1) + '. ' + s.name + '\n';
  emailBody += '   Funding: ' + s.funding + ' (' + s.round + ')\n';
  emailBody += '   ' + s.description + '\n';
  emailBody += '   Tech: ' + s.tech + ' | Investor: ' + s.investor + '\n';
  emailBody += '\n   >> GENERATE CONTENT: ' + url + '\n\n';
  emailBody += '   --------------------------------\n\n';
}

emailBody += '=============================================\n';
emailBody += 'X BUILDER INSIGHTS (from tracked accounts)\n';
emailBody += '=============================================\n\n';

for (let i = 0; i < xTips.length; i++) {
  const t = xTips[i];
  const post = (t.post_snippet || t.post_summary || '').substring(0, 800);
  const url = buildUrl(webhookBase, {
    type: 'x_tip',
    author: t.author,
    summary: t.post_summary || '',
    takeaway: t.practical_takeaway || '',
    post: post,
    post_url: t.post_url || ''
  });
  emailBody += (i + 1) + '. @' + t.author + '\n';
  emailBody += '   ' + (t.post_summary || '') + '\n';
  emailBody += '   Takeaway: ' + (t.practical_takeaway || '') + '\n';
  emailBody += '   Reel potential: ' + (t.reel_potential || '') + '\n';
  if (t.post_url) emailBody += '   Original post: ' + t.post_url + '\n';
  emailBody += '\n   >> GENERATE CONTENT: ' + url + '\n\n';
  emailBody += '   --------------------------------\n\n';
}

emailBody += '=============================================\n';
emailBody += 'TRENDING TOPICS (inspiration only — no auto-generate link)\n';
emailBody += '=============================================\n\n';

for (let i = 0; i < Math.min(trending.length, 5); i++) {
  const t = trending[i];
  emailBody += (i + 1) + '. ' + t.topic + '\n';
  emailBody += '   Platform: ' + t.platform + '\n';
  if (t.angle) emailBody += '   Angle: ' + t.angle + '\n';
  emailBody += '\n';
}

emailBody += 'Click startup or X Builder links above to generate a full Instagram content package.';

const allNames = startups.map(s => s.name).slice(0, 2);
const extra = xTips.length ? (' + ' + xTips.length + ' X tips') : '';
const subject = 'Daily Content Picks: ' + allNames.join(', ') + extra + ' + trending';

return [{ json: { emailBody, subject } }];

let data;
try { data = $input.first().json; } catch(e) { data = items[0].json; }
const query = data.query || data.params || data;

function g(key) {
  let val = '';
  if (query && query[key] !== undefined) val = query[key];
  else if (data && data[key] !== undefined) val = data[key];
  if (!val) return '';
  try { return decodeURIComponent(String(val)); } catch (e) { return String(val); }
}

const type = g('type') || 'startup';

if (type === 'x_tip') {
  const author = g('author') || 'Unknown';
  const summary = g('summary') || '';
  const takeaway = g('takeaway') || '';
  const post = g('post') || '';
  const post_url = g('post_url') || '';
  return [{
    json: {
      type: 'x_tip',
      author,
      summary,
      takeaway,
      post,
      post_url,
      name: '@' + author,
      funding_amount: '',
      round: '',
      description: post || summary,
      company: '',
      category: '',
      platform: 'X',
      snippet: '@' + author + ': ' + summary + ' | ' + takeaway
    }
  }];
}

const name = g('name') || g('headline') || g('topic') || 'Unknown';
const funding = g('funding') || '';
const round = g('round') || '';
const desc = g('desc') || g('detail') || g('angle') || '';
const company = g('company') || '';
const category = g('category') || '';
const platform = g('platform') || '';

return [{
  json: {
    type: 'startup',
    name,
    funding_amount: funding,
    round,
    description: desc,
    company,
    category,
    platform,
    snippet: name + ' raised ' + funding + ' in ' + round + '. ' + desc
  }
}];

let startup = {}, technical = {}, product = {}, market = {}, viral = '';

try { startup = $('Parse Selection').first().json || {}; } catch (e) { startup = { name: 'Unknown', funding_amount: 'Unknown', round: 'Unknown' }; }
try { const r = $('Research Technical').first().json || {}; technical = { content: r.choices?.[0]?.message?.content || '', citations: r.citations || [] }; } catch (e) { technical = { content: '', citations: [] }; }
try { const r = $('Research Product').first().json || {}; product = { content: r.choices?.[0]?.message?.content || '', citations: r.citations || [] }; } catch (e) { product = { content: '', citations: [] }; }
try { const r = $('Research Market & Competitors').first().json || {}; market = { content: r.choices?.[0]?.message?.content || '', citations: r.citations || [] }; } catch (e) { market = { content: '', citations: [] }; }
try { const r = $('Research Viral Angles').first().json || {}; viral = r.choices?.[0]?.message?.content || ''; } catch (e) { viral = ''; }

const name = startup.name || 'Unknown';
function nameMatchVariants(n) {
  const lower = String(n || '').toLowerCase().trim();
  const out = new Set();
  if (!lower) return [];
  out.add(lower);
  out.add(lower.replace(/\s/g, ''));
  out.add(lower.replace(/[^a-z0-9]/g, ''));
  for (const p of lower.split(/[\s.\-_]+/)) {
    if (p.length >= 3) out.add(p);
  }
  return [...out];
}
function textMentionsName(text, variants) {
  const c = String(text || '').toLowerCase();
  return variants.some(function (v) { return v.length >= 3 && c.indexOf(v) !== -1; });
}
const variants = nameMatchVariants(name);
const techHasName = textMentionsName(technical.content, variants);
const prodHasName = textMentionsName(product.content, variants);
const mktHasName = textMentionsName(market.content, variants);
const qualityCount = (techHasName ? 1 : 0) + (prodHasName ? 1 : 0) + (mktHasName ? 1 : 0);
const researchIsRelevant = qualityCount >= 2;
const warningMessage = researchIsRelevant ? '' : 'WARNING: Research may not be about the correct startup. Only ' + qualityCount + ' of 3 research streams mention ' + name + '. Write ONLY about confirmed facts. Keep content shorter. Do NOT fill gaps with information about other companies.';

function safeJson(s) {
  return String(s || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t').substring(0, 12000);
}

return [{ json: { startup_name: safeJson(name), funding_amount: safeJson(startup.funding_amount || 'Unknown'), round: safeJson(startup.round || 'Unknown'), original_snippet: safeJson(startup.snippet || ''), technical_research: safeJson(technical.content || 'No technical research found for ' + name), technical_sources: (technical.citations || []).slice(0, 5), product_research: safeJson(product.content || 'No product research found for ' + name), product_sources: (product.citations || []).slice(0, 5), market_research: safeJson(market.content || 'No market research found for ' + name), market_sources: (market.citations || []).slice(0, 5), viral_angles: safeJson(viral || 'No viral content research available'), research_quality: { tech: techHasName, product: prodHasName, market: mktHasName, score: qualityCount }, research_warning: safeJson(warningMessage), research_passed: researchIsRelevant } }];

