try {
  const cleaned = hookResponse.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  hooks = JSON.parse(cleaned);
} catch (e) {
  hooks = [{ style: 'BUILDER_PERSPECTIVE', hook: 'I found a ' + ($('Combine Research').first().json.funding_amount || '') + ' startup doing something nobody expected. Let me break it down.', why_it_works: 'Fallback hook' }];
}
const research = $('Combine Research').first().json;
const selectedIndex = Math.floor(Math.random() * hooks.length);
const selectedHook = hooks[selectedIndex] || hooks[0];
function safeJson(s) {
  return String(s || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t').substring(0, 12000);
}
const safeHook = { style: safeJson(selectedHook.style || ''), hook: safeJson(selectedHook.hook || ''), why_it_works: safeJson(selectedHook.why_it_works || '') };

return [{ json: { selected_hook: safeHook, all_hooks: hooks, startup_name: research.startup_name, funding_amount: research.funding_amount, round: research.round, original_snippet: research.original_snippet, technical_research: research.technical_research, technical_sources: research.technical_sources, product_research: research.product_research, product_sources: research.product_sources, market_research: research.market_research, market_sources: research.market_sources, viral_angles: research.viral_angles, research_warning: research.research_warning } }];

const research = $('Combine Research').first().json;
const hookData = $('Parse Best Hook').first().json;

let reelScript = 'Error';
try { const r = $('Generate Reel Script').first().json; reelScript = r.content?.[0]?.text || r.choices?.[0]?.message?.content || 'Failed'; } catch (e) { reelScript = 'Failed: ' + e.message; }

let carouselText = 'Error';
try { const r = $('Generate Carousel Text').first().json; carouselText = r.content?.[0]?.text || r.choices?.[0]?.message?.content || 'Failed'; } catch (e) { carouselText = 'Failed: ' + e.message; }

let caption = 'Error';
