}
return [{ json: { startup_name: safeJson(research.startup_name), funding_amount: safeJson(research.funding_amount), round: safeJson(research.round), reel_script: safeJson(reelScript), carousel_text: safeJson(carouselText), caption: safeJson(caption), all_hooks: hookData.all_hooks || [], selected_hook: hookData.selected_hook || {}, technical_sources: research.technical_sources || [], product_sources: research.product_sources || [], market_sources: research.market_sources || [], research_warning: safeJson(research.research_warning || '') } }];

const prepData = $('Prepare Refinement').first().json;
let refinedContent = 'Refinement failed';
try { refinedContent = items[0].json.content?.[0]?.text || items[0].json.choices?.[0]?.message?.content || 'Refinement failed'; } catch (e) { refinedContent = 'Refinement failed: ' + e.message; }

const sections = {};
const markers = ['REFINED REEL SCRIPT', 'REFINED CAROUSEL TEXT', 'REFINED CAPTION', 'QUALITY SCORE', 'REVIEWER NOTES'];
for (let i = 0; i < markers.length; i++) {
  const startMarker = '---' + markers[i] + '---';
  const startIdx = refinedContent.indexOf(startMarker);
  if (startIdx === -1) continue;
  const contentStart = startIdx + startMarker.length;
  let contentEnd = refinedContent.length;
  for (let j = i + 1; j < markers.length; j++) {
    const nextIdx = refinedContent.indexOf('---' + markers[j] + '---');
    if (nextIdx !== -1) { contentEnd = nextIdx; break; }
  }
  sections[markers[i]] = refinedContent.substring(contentStart, contentEnd).trim();
}

const reelScript = sections['REFINED REEL SCRIPT'] || prepData.reel_script || 'Not available';
const carouselText = sections['REFINED CAROUSEL TEXT'] || prepData.carousel_text || 'Not available';
const caption = sections['REFINED CAPTION'] || prepData.caption || 'Not available';
const qualityScore = sections['QUALITY SCORE'] || 'N/A';
const reviewerNotes = sections['REVIEWER NOTES'] || 'No notes';

let hooksSection = '';
const allHooks = prepData.all_hooks || [];
for (let i = 0; i < allHooks.length; i++) {
  hooksSection += (i + 1) + '. [' + (allHooks[i].style || 'HOOK') + '] ' + (allHooks[i].hook || '') + '\n';
  if (allHooks[i].why_it_works) hooksSection += '   Why: ' + allHooks[i].why_it_works + '\n';
