}

const allSources = [...(prepData.technical_sources || []), ...(prepData.product_sources || []), ...(prepData.market_sources || [])].filter(Boolean).slice(0, 8);

let emailBody = 'INSTAGRAM CONTENT PACKAGE: ' + prepData.startup_name + '\n';
emailBody += 'Funding: ' + prepData.funding_amount + ' (' + prepData.round + ')\n';
emailBody += 'Generated: ' + new Date().toISOString() + '\n\n';
emailBody += '========================================\nREEL SCRIPT (60-90 sec)\n========================================\n\n' + reelScript + '\n\n';
emailBody += '========================================\nCAROUSEL TEXT (7 slides)\n========================================\n\n' + carouselText + '\n\n';
emailBody += '========================================\nCAPTION + HASHTAGS\n========================================\n\n' + caption + '\n\n';
emailBody += '========================================\nQUALITY SCORE: ' + qualityScore + '\n========================================\n\n';
emailBody += 'REVIEWER NOTES:\n' + reviewerNotes + '\n\n';
emailBody += '========================================\nALTERNATIVE HOOKS (pick your favorite)\n========================================\n\n' + hooksSection + '\n';
emailBody += '========================================\nSOURCES\n========================================\n\n' + allSources.join('\n') + '\n';

return [{ json: { emailBody, subject: 'Instagram Ready: ' + prepData.startup_name + ' (' + prepData.funding_amount + ')', startup_name: prepData.startup_name, quality_score: qualityScore } }];

const p = $('Parse Selection').first().json || {};
return [{ json: {
  author: p.author || 'Unknown',
  post: p.post || '',
  summary: p.summary || '',
  takeaway: p.takeaway || '',
  snippet: p.snippet || '',
  post_url: p.post_url || ''
} }];

