try { tip = $('Parse X Tip Selection').first().json || {}; } catch (e) { tip = {}; }
let research = '';
let citations = [];
try {
  const r = $('Research Tip Deeper').first().json || {};
  research = r.choices?.[0]?.message?.content || '';
  citations = (r.citations || []).slice(0, 8);
} catch (e) { research = ''; }
const passed = research.length > 80;
const warning = passed ? '' : 'WARNING: Thin research. Keep the reel short and avoid strong factual claims.';
function safeJson(s) {
  return String(s || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t').substring(0, 12000);
}
return [{ json: {
  author: safeJson(tip.author || 'Unknown'),
  post: safeJson(tip.post || ''),
  summary: safeJson(tip.summary || ''),
  takeaway: safeJson(tip.takeaway || ''),
  snippet: safeJson(tip.snippet || ''),
  post_url: tip.post_url || '',
  deep_research: safeJson(research || 'No deep research found.'),
  research_sources: citations,
  research_warning: safeJson(warning),
  research_passed: passed
} }];

