const markers = ['REFINED REEL SCRIPT', 'REFINED CAROUSEL TEXT', 'REFINED CAPTION', 'QUALITY SCORE', 'REVIEWER NOTES'];
const sections = {};
for (let i = 0; i < markers.length; i++) {
  const sm = '---' + markers[i] + '---';
  const si = refinedContent.indexOf(sm);
  if (si === -1) continue;
  const cs = si + sm.length;
  let ce = refinedContent.length;
  for (let j = i + 1; j < markers.length; j++) {
    const ni = refinedContent.indexOf('---' + markers[j] + '---');
    if (ni !== -1) { ce = ni; break; }
  }
  sections[markers[i]] = refinedContent.substring(cs, ce).trim();
}
const reel = sections['REFINED REEL SCRIPT'] || prep.reel_script;
const carousel = sections['REFINED CAROUSEL TEXT'] || prep.carousel_text;
const caption = sections['REFINED CAPTION'] || prep.caption;
